import java.util.Arrays;

class Solution {
    public int hIndex(int[] citations) {
        int[] sorted = citations.clone();
        Arrays.sort(sorted);
        int length = sorted.length;
        for (int index = 0; index < length; index++) {
            int papers = length - index;
            if (sorted[index] >= papers) return papers;
        }
        return 0;
    }
}

